  {
    // 1. Check if the customer is eligible for IPO
    if (!isEligibleForIPO())
    {
      return false;
    }
    
    // 2. Check if the customer has any application with status APPROVAL for the same company
    for (Application app : getApplications())
    {
      if (app.getStatus() == ApplicationStatus.APPROVAL && app.getCompany() == company)
      {
        return false;
      }
    }
    
    // 3. Validate that shares > 0, amount > 0, and doc is not null
    if (shares <= 0 || amount <= 0.0 || doc == null)
    {
      return false;
    }
    
    // 4. Create a new Application object
    Application newApplication = IpoFactory.eINSTANCE.createApplication();
    newApplication.setCompany(company);
    newApplication.setShare(shares);
    newApplication.setAmountOfMoney(amount);
    newApplication.setAllowance(doc);
    
    // 5. Set the application's status to PENDING
    newApplication.setStatus(ApplicationStatus.PENDING);
    
    // 6. Add the application to the customer's applications list
    getApplications().add(newApplication);
    
    // 7. Return true
    return true;
  }

